  if (!this.backupEndpoint || !this.draftCode) return;
  try {
    const params = new URLSearchParams({ host_peer_id: this.hostPeer.id });
    await fetch(
      `${this.backupEndpoint}/p2p-draft-backup/${this.draftCode}?${params}`,
      { method: "DELETE" },
    );
  } catch {
    // Best-effort cleanup
  }
}

